<?php $title="TC Verification Records"; require "_top.php";
function tc_upload(){if(empty($_FILES['tc_file']['name'])||$_FILES['tc_file']['error']!==UPLOAD_ERR_OK)return ''; $dir=dirname(__DIR__).'/uploads/tc';if(!is_dir($dir))mkdir($dir,0775,true);$ext=strtolower(pathinfo($_FILES['tc_file']['name'],PATHINFO_EXTENSION));$allowed=['jpg','jpeg','png','webp','pdf'];if(!in_array($ext,$allowed,true))return ''; $name=uniqid('tc_',true).'.'.$ext;return move_uploaded_file($_FILES['tc_file']['tmp_name'],$dir.'/'.$name)?'uploads/tc/'.$name:'';}
if(isset($_POST['delete'])){$pdo->prepare('DELETE FROM tc_records WHERE id=?')->execute([(int)$_POST['delete']]);}
if(isset($_POST['save'])){$id=(int)($_POST['id']??0);$file=trim($_POST['old_file']??'');$up=tc_upload();if($up)$file=$up;if($id){$pdo->prepare('UPDATE tc_records SET admission_no=?,student_name=?,class_name=?,issue_date=?,tc_file=? WHERE id=?')->execute([trim($_POST['admission_no']),trim($_POST['student_name']),trim($_POST['class_name']),$_POST['issue_date']?:null,$file,$id]);}else{$pdo->prepare('INSERT INTO tc_records(admission_no,student_name,class_name,issue_date,tc_file) VALUES(?,?,?,?,?)')->execute([trim($_POST['admission_no']),trim($_POST['student_name']),trim($_POST['class_name']),$_POST['issue_date']?:null,$file]);}}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM tc_records WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$rows=$pdo->query('SELECT * FROM tc_records ORDER BY id DESC')->fetchAll();
?>
<div class="panel"><h2><?= $edit?'Edit TC Record':'Upload Transfer Certificate'?></h2><p class="muted">Upload the official TC as JPG, PNG, WebP or PDF. Public verification uses Admission Number.</p><form method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><input type="hidden" name="old_file" value="<?=e($edit['tc_file']??'')?>"><label>Admission Number<input name="admission_no" required value="<?=e($edit['admission_no']??'')?>"></label><label>Student Name<input name="student_name" value="<?=e($edit['student_name']??'')?>"></label><label>Class<input name="class_name" value="<?=e($edit['class_name']??'')?>"></label><label>Issue Date<input name="issue_date" type="date" value="<?=e($edit['issue_date']??'')?>"></label><label>TC File<input name="tc_file" type="file" accept="image/*,.pdf" <?=($edit?'':'required')?>></label><button class="primary" name="save">Save TC</button></form></div>
<div class="table-wrap panel"><table><tr><th>Admission No.</th><th>Student</th><th>Class</th><th>Issue Date</th><th>TC</th><th>Action</th></tr><?php foreach($rows as $r): ?><tr><td><b><?=e($r['admission_no'])?></b></td><td><?=e($r['student_name'])?></td><td><?=e($r['class_name'])?></td><td><?=e($r['issue_date'])?></td><td><a href="../<?=e($r['tc_file'])?>" target="_blank">View</a></td><td><a href="?edit=<?=$r['id']?>">Edit</a> <form method="post" style="display:inline"><button class="link danger" name="delete" value="<?=$r['id']?>">Delete</button></form></td></tr><?php endforeach;?></table></div>
<?php require "_bottom.php"; ?>